import type { CompileContext } from "./RuntimeCompiler.ts";

/**
 * The shared root AGENTS.md. Several targets read this file, so every adapter emits
 * identical contents and the result does not depend on compile order.
 */
export function renderAgentsMd(ctx: CompileContext): string {
  const { ir } = ctx;
  const lines: string[] = [
    `# ${ctx.config.project.name} — Agent Roster`,
    "",
    "Generated by Murmur. Edit the murmur/ directory, not this file.",
    "",
    "## Agents",
    "",
    ...ir.agents.map((a) => `- **${a.name}** — ${a.description}`),
  ];
  if (ir.subagents.length) {
    lines.push("", "## Subagents", "");
    lines.push(...ir.subagents.map((s) => `- **${s.name}** — ${s.description}`));
  }
  if (ir.skills.length) {
    lines.push("", "## Skills", "");
    lines.push(...ir.skills.map((s) => `- **${s.name}** — ${s.description}`));
  }
  if (ir.tools?.length) {
    lines.push("", "## Tools", "");
    lines.push(...ir.tools.map((t) => `- **${t.name}** — ${t.description} (\`${t.command}\`)`));
  }
  if (ir.instructions.length) {
    lines.push("", "## Instructions");
    for (const i of ir.instructions) {
      lines.push("", `### ${i.name} (\`${i.applyTo}\`)`, "", i.rules.trim());
    }
  }
  return `${lines.join("\n")}\n`;
}
